// ============================================================
// GENERAL LEDGER (GL) — standard chart of accounts, generated
// programmatically so every scheme gets its own dedicated GLs.
// Numbering: Assets 1xxxx · Liabilities 2xxxx · Income 4xxxx · Expense 5xxxx
// ============================================================

const GL_COUNTERS = { Asset: 10000, Liability: 20000, Income: 40000, Expense: 50000 };
function nextGLCode(type) { GL_COUNTERS[type] += 1; return String(GL_COUNTERS[type]); }

const LOAN_GL_TEMPLATE = [
  ["principalOutstanding", "Principal Outstanding GL", "Asset"],
  ["interestReceivable", "Interest Receivable GL", "Asset"],
  ["interestIncome", "Interest Income GL", "Income"],
  ["penalInterest", "Penal Interest GL", "Income"],
  ["processingFeeIncome", "Processing Fee Income GL", "Income"],
  ["documentationFeeIncome", "Documentation Fee Income GL", "Income"],
  ["insuranceCollection", "Insurance Collection GL", "Liability"],
  ["emiCollection", "EMI Collection GL", "Asset"],
  ["npaLoan", "NPA Loan GL", "Asset"],
  ["provisionForNPA", "Provision for NPA GL", "Liability"],
  ["writeOff", "Write-off GL", "Expense"],
];
const DEPOSIT_GL_TEMPLATE = [
  ["deposit", "Deposit GL", "Liability"],
  ["interestPayable", "Interest Payable GL", "Liability"],
  ["interestExpense", "Interest Expense GL", "Expense"],
  ["penalty", "Penalty GL", "Income"],
  ["chargesIncome", "Charges Income GL", "Income"],
];

function buildGLMasters() {
  const masters = [];
  const map = {};
  const add = (schemeKey, role, name, type, category) => {
    const code = nextGLCode(type);
    masters.push({ code, name, type, category, status: "Active" });
    if (!map[schemeKey]) map[schemeKey] = {};
    map[schemeKey][role] = code;
  };

  // Common / control GLs (not scheme-specific — used as counter-legs for teller ops)
  add("Common", "cash", "Cash GL", "Asset", "Common");
  add("Common", "chequeClearing", "Cheque Clearing GL", "Asset", "Common");
  add("Common", "transferClearing", "Funds Transfer Clearing GL", "Asset", "Common");
  add("Common", "neftClearing", "NEFT Clearing / Suspense GL", "Asset", "Common");
  add("Common", "rtgsClearing", "RTGS Clearing / Suspense GL", "Asset", "Common");
  add("Common", "impsClearing", "IMPS Clearing / Suspense GL", "Asset", "Common");
  add("Common", "upiClearing", "UPI Clearing / Suspense GL", "Asset", "Common");
  add("Common", "transferChargesIncome", "Fund Transfer Charges Income GL", "Income", "Common");
  add("Common", "gstPayable", "IGST Payable GL", "Liability", "Common");
  add("Common", "cgstPayable", "CGST Payable GL", "Liability", "Common");
  add("Common", "sgstPayable", "SGST Payable GL", "Liability", "Common");
  add("Common", "memberShareCapital", "Member Share Capital GL", "Liability", "Common");
  add("Common", "membershipFeeIncome", "Membership Fee Income GL", "Income", "Common");
  add("Common", "reserveFund", "Reserve Fund GL", "Liability", "Common");
  add("Common", "salaryExpense", "Staff Salary Expense GL", "Expense", "Common");
  add("Common", "pfPayable", "Provident Fund Payable GL", "Liability", "Common");
  add("Common", "professionalTaxPayable", "Professional Tax Payable GL", "Liability", "Common");
  add("Common", "callDeposit", "Call Deposit GL", "Liability", "Common");
  add("Common", "callDepositInterestExpense", "Call Deposit Interest Expense GL", "Expense", "Common");
  add("Common", "misDeposit", "MIS Deposit GL", "Liability", "Common");
  add("Common", "misInterestExpense", "MIS Interest Expense GL", "Expense", "Common");
  add("Common", "slrInvestment", "SLR Investment GL", "Asset", "Common");
  add("Common", "slrInterestIncome", "SLR Investment Interest Income GL", "Income", "Common");
  add("Common", "slrProfitOnSale", "SLR Profit on Sale GL", "Income", "Common");
  add("Common", "slrLossOnSale", "SLR Loss on Sale GL", "Expense", "Common");
  add("Common", "tdsPayable", "TDS Payable GL", "Liability", "Common");
  add("Common", "lockerSecurityDeposit", "Locker Security Deposit GL", "Liability", "Common");
  add("Common", "lockerRentIncome", "Locker Rent Income GL", "Income", "Common");
  add("Common", "npaProvisionExpense", "NPA Provision Expense GL", "Expense", "Common");
  add("Common", "npaProvisionLiability", "Provision for NPA GL", "Liability", "Common");

  // Savings
  add("Savings", "deposit", "Savings Deposit GL", "Liability", "Savings");
  add("Savings", "interestPayable", "Savings Interest Payable GL", "Liability", "Savings");
  add("Savings", "interestExpense", "Savings Interest Expense GL", "Expense", "Savings");
  add("Savings", "penalty", "Savings Penalty GL", "Income", "Savings");
  add("Savings", "chargesIncome", "Savings Charges Income GL", "Income", "Savings");

  // Current
  add("Current", "deposit", "Current Deposit GL", "Liability", "Current");
  add("Current", "chargesIncome", "Current Charges Income GL", "Income", "Current");
  add("Current", "penaltyIncome", "Current Penalty Income GL", "Income", "Current");

  // Recurring Deposit
  add("RD", "deposit", "RD Deposit GL", "Liability", "Recurring Deposit");
  add("RD", "interestPayable", "RD Interest Payable GL", "Liability", "Recurring Deposit");
  add("RD", "interestExpense", "RD Interest Expense GL", "Expense", "Recurring Deposit");
  add("RD", "prematureClosure", "RD Premature Closure GL", "Income", "Recurring Deposit");
  add("RD", "penalty", "RD Penalty GL", "Income", "Recurring Deposit");

  // Fixed Deposit
  add("FD", "deposit", "FD Deposit GL", "Liability", "Fixed Deposit");
  add("FD", "interestPayable", "FD Interest Payable GL", "Liability", "Fixed Deposit");
  add("FD", "interestExpense", "FD Interest Expense GL", "Expense", "Fixed Deposit");
  add("FD", "prematureClosure", "FD Premature Closure GL", "Income", "Fixed Deposit");
  add("FD", "tdsPayable", "TDS Payable GL", "Liability", "Fixed Deposit");

  // Loan schemes — every loan product gets its own dedicated set of 11 GLs
  LOAN_TYPES.forEach((loanType) => {
    LOAN_GL_TEMPLATE.forEach(([role, label, type]) => {
      add(loanType, role, `${loanType} ${label}`, type, loanType);
    });
  });

  return { masters, map };
}

