function buildInitialBanks() {
  return INITIAL_BANKS_RAW.map((b, i) => {
    const code = nextGLCode("Asset");
    INITIAL_GL_MASTERS.push({ code, name: `${b.name} GL`, type: "Asset", category: "Bank Accounts", status: "Active" });
    return { id: "BNK" + String(i + 1).padStart(3, "0"), ...b, glCode: code, status: "Active" };
  });
}
