const DEPOSIT_SCHEME_ROLES = ["deposit", "interestPayable", "interestExpense", "penalty", "chargesIncome"];
const LOAN_SCHEME_ROLES = ["principalOutstanding", "interestReceivable", "interestIncome", "penalInterest", "processingFeeIncome", "documentationFeeIncome", "insuranceCollection", "emiCollection", "npaLoan", "provisionForNPA", "writeOff"];

function isSchemeFullyMapped(schemeKey, isLoan) {
  const required = isLoan ? LOAN_SCHEME_ROLES : DEPOSIT_SCHEME_ROLES.filter((r) => !(schemeKey === "Current" && (r === "interestPayable" || r === "interestExpense" || r === "penalty")));
  const mapping = SCHEME_GL_MAP[schemeKey] || {};
  return required.every((r) => !!mapping[r]);
}

