const MONTH_INDEX = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
function parseReportDate(str, refDate) {
  if (!str) return null;
  if (str === "Today" || str === "Just now") return refDate || new Date(2026, 6, 24);
  const parts = String(str).trim().split(" ");
  if (parts.length === 3 && MONTH_INDEX[parts[1]] !== undefined) return new Date(Number(parts[2]), MONTH_INDEX[parts[1]], Number(parts[0]));
  if (parts.length === 2 && MONTH_INDEX[parts[1]] !== undefined) return new Date(2026, MONTH_INDEX[parts[1]], Number(parts[0]));
  return null;
}

