function makeDefaultSmsTemplate(type) {
  const base = {
    "Loan EMI Reminder": "Dear {{CustomerName}}, your EMI of {{EMIAmount}} for loan {{LoanAccountNo}} is due on {{DueDate}}. Please ensure sufficient balance. -{{SocietyName}}",
    "EMI Due Today": "Dear {{CustomerName}}, your EMI of {{EMIAmount}} for loan {{LoanAccountNo}} is due TODAY. -{{SocietyName}}",
    "EMI Overdue": "Dear {{CustomerName}}, your EMI for loan {{LoanAccountNo}} is overdue. Overdue amount: {{OverdueAmount}}. Please pay immediately. -{{SocietyName}}",
    "First Reminder Notice": "Dear {{CustomerName}}, this is a reminder that your loan {{LoanAccountNo}} has an outstanding overdue amount of {{OverdueAmount}}. Kindly clear at the earliest. -{{SocietyName}}",
    "Second Reminder Notice": "Dear {{CustomerName}}, despite our earlier reminder, loan {{LoanAccountNo}} remains overdue by {{OverdueAmount}}. Please contact {{BranchName}} at {{BranchContactNo}}. -{{SocietyName}}",
    "Final Reminder Notice": "Dear {{CustomerName}}, FINAL REMINDER: loan {{LoanAccountNo}} overdue amount {{OverdueAmount}} must be cleared immediately to avoid further action. -{{SocietyName}}",
    "Loan Account Overdue Notice": "Dear {{CustomerName}}, your loan account {{LoanAccountNo}} ({{LoanScheme}}) is classified overdue. Total outstanding: {{TotalOutstanding}}. -{{SocietyName}}",
    "Recovery Reminder": "Dear {{CustomerName}}, our recovery team will be contacting you regarding loan {{LoanAccountNo}}. Overdue: {{OverdueAmount}}. -{{SocietyName}}",
    "Demand Notice": "Dear {{CustomerName}}, this is a formal demand notice for loan {{LoanAccountNo}}. Outstanding: {{TotalOutstanding}}. Contact {{BranchName}} immediately. -{{SocietyName}}",
    "Loan Closure / Final Payment Reminder": "Dear {{CustomerName}}, your loan {{LoanAccountNo}} is nearing closure. Final payment of {{EMIAmount}} is due on {{DueDate}}. -{{SocietyName}}",
  };
  return base[type] || `Dear {{CustomerName}}, regarding loan {{LoanAccountNo}}. -{{SocietyName}}`;
}
function makeDefaultWhatsappTemplate(type) {
  const base = {
    "Loan EMI Reminder": "Hi {{CustomerName}}, your EMI of {{EMIAmount}} for loan {{LoanAccountNo}} ({{LoanScheme}}) is due on {{DueDate}}. Pay now: {{PaymentLink}}",
    "EMI Due Today": "Hi {{CustomerName}}, your EMI of {{EMIAmount}} for loan {{LoanAccountNo}} is due today. Pay now: {{PaymentLink}}",
    "Overdue Reminder": "Hi {{CustomerName}}, loan {{LoanAccountNo}} has an overdue amount of {{OverdueAmount}}. Please pay at the earliest: {{PaymentLink}}",
    "Recovery Notice": "Hi {{CustomerName}}, your loan {{LoanAccountNo}} requires urgent attention. Overdue: {{OverdueAmount}}. Contact {{BranchName}} at {{BranchContactNo}}.",
    "Demand Notice": "Hi {{CustomerName}}, formal demand notice for loan {{LoanAccountNo}}. Total outstanding: {{TotalOutstanding}}. Contact us immediately.",
    "Payment Confirmation": "Hi {{CustomerName}}, we've received your payment for loan {{LoanAccountNo}}. Thank you! -{{SocietyName}}",
    "Loan Statement": "Hi {{CustomerName}}, your loan statement for {{LoanAccountNo}} is ready. Total outstanding: {{TotalOutstanding}}.",
    "Important Account Notifications": "Hi {{CustomerName}}, important update regarding your account with {{SocietyName}}. Please contact {{BranchName}}.",
  };
  return base[type] || `Hi {{CustomerName}}, regarding loan {{LoanAccountNo}}. -{{SocietyName}}`;
}
