// ==================== Voter List (Member section) ====================
// Eligibility follows common Co-operative Societies bye-law practice: only Regular Members (not
// Nominal Members) vote, subject to a minimum membership duration, a minimum share qualification,
// and (commonly) not being in default on any loan. All thresholds are configurable since bye-laws differ.
const DEFAULT_VOTER_ELIGIBILITY_CONFIG = { minMembershipMonths: 6, minShares: 10, excludeNominalMembers: true, excludeOverdueLoanMembers: true };

function computeVoterEligibility(member, customerLoans, asOfDateObj, config) {
  const reasons = [];
  if (member.status !== "Active") reasons.push("Membership not Active");
  if (config.excludeNominalMembers && member.memberType !== "Regular Member") reasons.push("Nominal Member — no voting rights under bye-laws");
  const admissionDateObj = parseReportDate(member.admissionDate, asOfDateObj);
  let membershipMonths = null;
  if (admissionDateObj) {
    membershipMonths = (asOfDateObj.getFullYear() - admissionDateObj.getFullYear()) * 12 + (asOfDateObj.getMonth() - admissionDateObj.getMonth());
    if (asOfDateObj.getDate() < admissionDateObj.getDate()) membershipMonths -= 1;
    if (membershipMonths < config.minMembershipMonths) reasons.push(`Membership only ${Math.max(0, membershipMonths)} month(s) — minimum ${config.minMembershipMonths} required`);
  }
  if ((member.shares || 0) < config.minShares) reasons.push(`Holds ${member.shares || 0} share(s) — minimum ${config.minShares} required`);
  if (config.excludeOverdueLoanMembers) {
    const hasDefaultedLoan = customerLoans.some((l) => l.status === "Overdue" || l.status === "NPA");
    if (hasDefaultedLoan) reasons.push("Has an overdue/NPA loan — ineligible per bye-laws until regularized");
  }
  return { eligible: reasons.length === 0, reasons, membershipMonths };
}

// ==================== Regulatory MIS Report (Maharashtra Cooperative Commissioner circular) ====================
// Scoring bands per the official monthly MIS classification table. Bracket boundaries in the source
// circular overlap slightly at a few points (e.g. CRR's "1% असल्यास" vs "1 ते 2%", SLR's "किमान 25%"
// vs "25% ते 30%") — the interpretation below reads the first band as "at/near the regulatory minimum"
// and treats brackets as non-overlapping thereafter. This should be verified against the Society's own
// compliance officer's reading before being relied on for actual regulatory submission.
function scoreCdRatio(pct) {
  if (pct >= 60 && pct < 70) return 40;
  if ((pct >= 55 && pct < 60) || (pct >= 70 && pct < 80)) return 30;
  return 0;
}
function scoreOverduePct(pct) {
  if (pct < 5) return 30;
  if (pct < 10) return 20;
  if (pct < 15) return 10;
  return 0;
}
function scoreCRR(pct) {
  if (pct < 1) return 0;
  if (pct <= 1) return 5;
  if (pct <= 2) return 4;
  if (pct <= 3) return 3;
  if (pct <= 4) return 2;
  return 1;
}
function scoreSLR(pct) {
  if (pct < 25 || pct > 40) return 0;
  if (pct <= 25) return 20;
  if (pct <= 30) return 15;
  if (pct <= 35) return 10;
  return 5;
}
function scoreProfitLoss(netProfit) { return netProfit >= 0 ? 5 : 0; }
function misGradeLabel(totalScore) {
  if (totalScore > 75) return "अ (A)";
  if (totalScore > 50) return "ब (B)";
  if (totalScore > 25) return "क (C)";
  return "ड (D)";
}

function substituteCommVariables(template, loan, customer, societyName, branchName, branchContact) {
  return template
    .replace(/\{\{CustomerName\}\}/g, loan.customer || "")
    .replace(/\{\{LoanAccountNo\}\}/g, loan.id || "")
    .replace(/\{\{LoanScheme\}\}/g, loan.type || "")
    .replace(/\{\{EMIAmount\}\}/g, inr(loan.emi || 0))
    .replace(/\{\{DueDate\}\}/g, loan.due || "—")
    .replace(/\{\{OverdueAmount\}\}/g, inr(loan.dueAmount || 0))
    .replace(/\{\{TotalOutstanding\}\}/g, inr(loan.dueAmount || 0))
    .replace(/\{\{BranchName\}\}/g, branchName || "")
    .replace(/\{\{BranchContactNo\}\}/g, branchContact || "022-00000000")
    .replace(/\{\{SocietyName\}\}/g, societyName || "")
    .replace(/\{\{PaymentLink\}\}/g, `https://pay.example.com/${loan.id}`);
}

function isSeniorCitizen(customer, asOfIso) {
  if (!customer?.dob) return false;
  const [by, bm, bd] = customer.dob.split("-").map(Number);
  const [ay, am, ad] = asOfIso.split("-").map(Number);
  let age = ay - by;
  if (am < bm || (am === bm && ad < bd)) age--;
  return age >= 60;
}

// Intra-state supplies attract CGST + SGST (split equally between the two); inter-state supplies
// attract a single IGST instead. Determined by comparing the customer's registered state against
// the Society's own registered state (settingsForm.state).
function computeGstSplit(amount, customerState, societyState, gstConfig) {
  const amt = Number(amount) || 0;
  const isIntraState = !customerState || !societyState || customerState === societyState;
  if (isIntraState) {
    const cgst = Math.round(amt * (gstConfig.cgstRate / 100) * 100) / 100;
    const sgst = Math.round(amt * (gstConfig.sgstRate / 100) * 100) / 100;
    return { isIntraState: true, cgst, sgst, igst: 0, total: Math.round((cgst + sgst) * 100) / 100 };
  }
  const igst = Math.round(amt * (gstConfig.igstRate / 100) * 100) / 100;
  return { isIntraState: false, cgst: 0, sgst: 0, igst, total: igst };
}

function numberToWordsIndian(num) {
  const n = Math.round(Number(num) || 0);
  if (n === 0) return "Zero";
  const ones = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
  const tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
  function twoDigits(x) {
    if (x < 20) return ones[x];
    return tens[Math.floor(x / 10)] + (x % 10 ? " " + ones[x % 10] : "");
  }
  function threeDigits(x) {
    if (x >= 100) return ones[Math.floor(x / 100)] + " Hundred" + (x % 100 ? " " + twoDigits(x % 100) : "");
    return twoDigits(x);
  }
  let rem = Math.abs(n);
  const crore = Math.floor(rem / 10000000); rem %= 10000000;
  const lakh = Math.floor(rem / 100000); rem %= 100000;
  const thousand = Math.floor(rem / 1000); rem %= 1000;
  const hundred = rem;
  const parts = [];
  if (crore) parts.push(threeDigits(crore) + " Crore");
  if (lakh) parts.push(threeDigits(lakh) + " Lakh");
  if (thousand) parts.push(threeDigits(thousand) + " Thousand");
  if (hundred) parts.push(threeDigits(hundred));
  return (n < 0 ? "Minus " : "") + parts.join(" ");
}

// Marathi does not compose 21-99 from tens+ones the way English does — each number 0-99 has its
// own distinct word, so this uses a full lookup table rather than a formula.
const MARATHI_NUM_WORDS = [
  "शून्य", "एक", "दोन", "तीन", "चार", "पाच", "सहा", "सात", "आठ", "नऊ", "दहा",
  "अकरा", "बारा", "तेरा", "चौदा", "पंधरा", "सोळा", "सतरा", "अठरा", "एकोणीस", "वीस",
  "एकवीस", "बावीस", "तेवीस", "चोवीस", "पंचवीस", "सव्वीस", "सत्तावीस", "अठ्ठावीस", "एकोणतीस", "तीस",
  "एकतीस", "बत्तीस", "तेहतीस", "चौतीस", "पस्तीस", "छत्तीस", "सदतीस", "अडतीस", "एकोणचाळीस", "चाळीस",
  "एक्केचाळीस", "बेचाळीस", "त्रेचाळीस", "चव्वेचाळीस", "पंचेचाळीस", "सेहेचाळीस", "सत्तेचाळीस", "अठ्ठेचाळीस", "एकोणपन्नास", "पन्नास",
  "एक्कावन्न", "बावन्न", "त्रेपन्न", "चोपन्न", "पंचावन्न", "छप्पन्न", "सत्तावन्न", "अठ्ठावन्न", "एकोणसाठ", "साठ",
  "एकसष्ट", "बासष्ट", "त्रेसष्ट", "चौसष्ट", "पासष्ट", "सहासष्ट", "सदुसष्ट", "अडुसष्ट", "एकोणसत्तर", "सत्तर",
  "एक्काहत्तर", "बहात्तर", "त्र्याहत्तर", "चौर्‍याहत्तर", "पंच्याहत्तर", "शहात्तर", "सत्याहत्तर", "अठ्ठ्याहत्तर", "एकोणऐंशी", "ऐंशी",
  "एक्क्याऐंशी", "ब्याऐंशी", "त्र्याऐंशी", "चौऱ्याऐंशी", "पंच्याऐंशी", "शहाऐंशी", "सत्त्याऐंशी", "अठ्ठ्याऐंशी", "एकोणनव्वद", "नव्वद",
  "एक्क्याण्णव", "ब्याण्णव", "त्र्याण्णव", "चौऱ्याण्णव", "पंच्याण्णव", "शहाण्णव", "सत्त्याण्णव", "अठ्ठ्याण्णव", "नव्याण्णव",
];
function numberToWordsMarathi(num) {
  const n = Math.round(Number(num) || 0);
  if (n === 0) return "शून्य";
  function twoDigits(x) { return MARATHI_NUM_WORDS[x]; }
  function threeDigits(x) {
    if (x >= 100) return MARATHI_NUM_WORDS[Math.floor(x / 100)] + " शे" + (x % 100 ? " " + twoDigits(x % 100) : "");
    return twoDigits(x);
  }
  let rem = Math.abs(n);
  const crore = Math.floor(rem / 10000000); rem %= 10000000;
  const lakh = Math.floor(rem / 100000); rem %= 100000;
  const thousand = Math.floor(rem / 1000); rem %= 1000;
  const hundred = rem;
  const parts = [];
  if (crore) parts.push(threeDigits(crore) + " कोटी");
  if (lakh) parts.push(threeDigits(lakh) + " लाख");
  if (thousand) parts.push(threeDigits(thousand) + " हजार");
  if (hundred) parts.push(threeDigits(hundred));
  return (n < 0 ? "उणे " : "") + parts.join(" ");
}

