function AccountDetailFields({ account, kyc, customerPhoto, kycType, mobile, onChange, onViewKyc, kycWarning, pan, aadhaar, memberNo, lienLoanId, branch, isInflow, txnAmount }) {
  const meta = kycMeta[kyc] || { color: "#66707D", bg: "#F5F7FA" };
  const statusMeta = accountStatusMeta[account.status] || { color: "#66707D", bg: "#F5F7FA" };
  const glKey = SCHEME_TO_GL_KEY[account.type];
  const glCode = SCHEME_GL_MAP[glKey]?.deposit;
  const glMaster = INITIAL_GL_MASTERS.find((g) => g.code === glCode);
  const amt = Number(txnAmount) || 0;
  const balanceAfter = amt > 0 ? (isInflow ? account.deposit + amt : account.deposit - amt) : null;
  return (
    <div className="cbs-acct-detail-panel" style={{ flexDirection: "column", alignItems: "stretch" }}>
      <div style={{ display: "flex", gap: 12, alignItems: "flex-start" }}>
        {customerPhoto && (
          <img src={customerPhoto} alt={account.customer} style={{ width: 52, height: 52, borderRadius: "50%", objectFit: "cover", border: "2px solid var(--white)", flexShrink: 0 }} />
        )}
        <div className="cbs-acct-detail-grid" style={{ flex: 1 }}>
          <div className="cbs-acct-detail-field"><label>Branch</label><div className="cbs-acct-detail-value">{branch || "—"}</div></div>
          <div className="cbs-acct-detail-field"><label><Lock size={9} style={{ verticalAlign: -1, marginRight: 3 }} />Account Number</label><div className="cbs-acct-detail-value cbs-mono">{account.id}</div></div>
          <div className="cbs-acct-detail-field"><label>GL Head</label><div className="cbs-acct-detail-value cbs-mono" style={{ fontSize: 11.5 }}>{glCode || "—"} — {glMaster?.name || account.type}</div></div>
          <div className="cbs-acct-detail-field"><label><Lock size={9} style={{ verticalAlign: -1, marginRight: 3 }} />Customer Name</label><div className="cbs-acct-detail-value">{account.customer}</div></div>
          <div className="cbs-acct-detail-field"><label>Mode of Operation</label><div className="cbs-acct-detail-value">{account.holdingType || "—"}</div></div>
          <div className="cbs-acct-detail-field"><label>Member No.</label><div className="cbs-acct-detail-value cbs-mono">{memberNo || "Not a member"}</div></div>
          <div className="cbs-acct-detail-field"><label><Lock size={9} style={{ verticalAlign: -1, marginRight: 3 }} />Available Balance</label><div className="cbs-acct-detail-value cbs-mono">{inr(account.deposit)}</div></div>
          {balanceAfter !== null && <div className="cbs-acct-detail-field"><label>Balance After Transaction</label><div className="cbs-acct-detail-value cbs-mono" style={{ fontWeight: 700, color: balanceAfter < 0 ? "var(--danger)" : "var(--navy)" }}>{inr(balanceAfter)}</div></div>}
          {amt > 0 && <div className="cbs-acct-detail-field" style={{ gridColumn: "1 / -1" }}><label>Amount in Words</label><div className="cbs-acct-detail-value" style={{ fontStyle: "italic" }}>Rupees {numberToWordsIndian(amt)} Only</div></div>}
          <div className="cbs-acct-detail-field"><label>PAN — Aadhaar No.</label><div className="cbs-acct-detail-value cbs-mono" style={{ fontSize: 11.5 }}>{pan || "—"} — {aadhaar || "—"}</div></div>
          <div className="cbs-acct-detail-field"><label>KYC Status</label><span className="cbs-chip" style={{ color: meta.color, background: meta.bg }}>{kyc || "Unknown"}</span></div>
          <div className="cbs-acct-detail-field"><label>KYC Type</label><div className="cbs-acct-detail-value">{kycType || "—"}</div></div>
          <div className="cbs-acct-detail-field"><label>Mobile Number</label><div className="cbs-acct-detail-value cbs-mono">{mobile || "—"}</div></div>
          <div className="cbs-acct-detail-field"><label>Account Status</label><span className="cbs-chip" style={{ color: statusMeta.color, background: statusMeta.bg }}>{account.status}</span></div>
          {lienLoanId && <div className="cbs-acct-detail-field" style={{ gridColumn: "1 / -1" }}><label>Lien Info</label><div className="cbs-acct-detail-value" style={{ color: "var(--danger)" }}><Lock size={11} style={{ verticalAlign: -1, marginRight: 3 }} />Marked as collateral for loan {lienLoanId} — withdrawal restricted</div></div>}
        </div>
      </div>
      {kycWarning && (
        <div style={{ marginTop: 10, background: "var(--danger-bg)", border: "1px solid var(--danger)", borderRadius: 8, padding: "9px 12px", fontSize: 12.5, color: "var(--danger)", display: "flex", alignItems: "center", gap: 8, fontWeight: 600 }}>
          <ShieldAlert size={14} style={{ flexShrink: 0 }} /> {kycWarning}
        </div>
      )}
      <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
        {onViewKyc && <button type="button" className="cbs-report-btn" onClick={onViewKyc}><ShieldCheck size={12} /> View KYC Details</button>}
        {onChange && <button type="button" className="cbs-report-btn" onClick={onChange}>Change</button>}
      </div>
    </div>
  );
}

function PhotoUploadField({ label, value, onChange, round }) {
  return (
    <div className="cbs-form-field">
      <label className="cbs-field-label">{label}</label>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        {value && (
          <img src={value} alt={label} style={{ width: 48, height: 48, objectFit: "cover", borderRadius: round ? "50%" : 8, border: "1px solid var(--border)", flexShrink: 0 }} />
        )}
        <input
          className="cbs-input"
          type="file"
          accept="image/*"
          onChange={(e) => {
            const file = e.target.files && e.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = () => onChange(reader.result);
            reader.readAsDataURL(file);
          }}
        />
      </div>
    </div>
  );
}

