    setLeaveRequests((rs) => rs.map((r) => (r.id === req.id ? { ...r, status: "Cancelled", cancelledBy: currentUser.name, cancelledDate: bankDateLabel } : r)));
    logSettingChange("Leave Request", req.id, req.status, `Cancelled by ${currentUser.name}`);
    setFlash(`${req.id} cancelled${wasApproved ? ` — ${req.days} day(s) restored to ${req.employeeName}'s ${req.leaveType} balance` : ""}`);
