  function previewPayroll(month, year) {
    const activeEmployees = users.filter((u) => u.status === "Active");
    const alreadyProcessed = payrollRuns.some((p) => p.month === month && p.year === year);
    const entries = activeEmployees.map((emp) => {
      const unpaidDays = getUnpaidLeaveDaysInMonth(emp.employeeId, month, year);
      const b = computeSalaryBreakup(emp, unpaidDays);
      return { employeeId: emp.employeeId, name: emp.name, designation: emp.designation || "—", basic: emp.basicSalary, hra: emp.hra, da: emp.da, specialAllowance: emp.specialAllowance, unpaidLeaveDays: unpaidDays, ...b, bankAccountNumber: emp.bankAccountNumber, bankName: emp.bankName };
    });
    const totalGross = Math.round(entries.reduce((s, e) => s + e.gross, 0) * 100) / 100;
    const totalPF = Math.round(entries.reduce((s, e) => s + e.pf, 0) * 100) / 100;
    const totalProfTax = Math.round(entries.reduce((s, e) => s + e.professionalTax, 0) * 100) / 100;
    const totalLOP = Math.round(entries.reduce((s, e) => s + e.lopDeduction, 0) * 100) / 100;
    const totalNet = Math.round(entries.reduce((s, e) => s + e.netSalary, 0) * 100) / 100;
    return { month, year, entries, totalGross, totalPF, totalProfTax, totalLOP, totalNet, alreadyProcessed, employeeCount: entries.length };
  }

  function processPayroll(month, year) {
    if (isDayClosed) { setFlash(`${bankDateLabel} is closed for transactions. Reopen the day in Settings to make corrections.`); return; }
    const preview = previewPayroll(month, year);
    if (preview.alreadyProcessed) { setFlash(`Payroll for ${month} ${year} has already been processed`); return; }
    if (preview.employeeCount === 0) { setFlash("No active employees to process payroll for"); return; }

    const runId = "PR" + String(payrollRuns.length + 1).padStart(4, "0");
    postGL("Payroll", `Payroll processed for ${month} ${year} — ${runId} (${preview.employeeCount} employee(s))${preview.totalLOP > 0 ? `, LOP ${inr(preview.totalLOP)}` : ""}`, [
      { code: SALARY_EXPENSE_GL, debit: Math.round((preview.totalGross - preview.totalLOP) * 100) / 100 },
      { code: PF_PAYABLE_GL, credit: preview.totalPF },
      { code: PROFESSIONAL_TAX_PAYABLE_GL, credit: preview.totalProfTax },
      { code: CASH_GL, credit: preview.totalNet },
    ]);
    const run = { id: runId, month, year, periodLabel: `${month} ${year}`, processedDate: bankDateLabel, processedBy: currentUser.name, ...preview };
    setPayrollRuns((r) => [run, ...r]);
    setFlash(`${runId}: Payroll processed for ${month} ${year} — ${inr(preview.totalNet)} net paid to ${preview.employeeCount} employee(s)`);
    return runId;
  }

