  function submitMember(e) {
    e.preventDefault();
    const cust = selectedMemberCustomer;
    const shares = Number(memberForm.shares);
    if (!cust || !shares || shares <= 0) { setFlash("Search and select a customer, and enter number of shares"); return; }
    const maxNum = members.reduce((m, x) => Math.max(m, parseInt(x.id, 10) || 0), 1000);
    const id = String(maxNum + 1);
    const shareCapital = shares * SHARE_VALUE;
    const maxCertIssued = members.reduce((m, x) => Math.max(m, x.shareCertTo || 0), 0);
    const shareCertFrom = maxCertIssued + 1;
    const shareCertTo = maxCertIssued + shares;
    const newMember = { id, customerNo: cust.id, name: cust.name, memberType: memberForm.memberType, shares, shareCapital, admissionDate: bankDateLabel, nominee: memberForm.nominee || "—", nomineeRelation: memberForm.nominee ? memberForm.nomineeRelation : "", status: "Active", admittedBy: currentUser.employeeId, shareCertFrom, shareCertTo };
    setMembers((m) => [newMember, ...m]);
    postGL("Members", `Share capital contribution — ${cust.name} (${id})`, [
      { code: CASH_GL, debit: shareCapital },
      { code: MEMBER_SHARE_CAPITAL_GL, credit: shareCapital },
    ]);
    logMembershipTransaction("Admission", id, cust.name, `Admitted as ${memberForm.memberType} — ${shares} shares (Cert. No. ${shareCertFrom}–${shareCertTo}), ${inr(shareCapital)} collected`);
    setNewMemberNo(id);
    setFlash(`Member number ${id} created — ${shares} shares (${inr(shareCapital)}) collected, Certificate No. ${shareCertFrom}–${shareCertTo}`);
    setMemberForm({ customerNo: "", memberType: "Regular Member", shares: "", nominee: "", nomineeRelation: "", nomineeRelationIsOther: false });
    setMemberCustomerQuery("");
  }

