  function parseTargetBulkFile(file) {
    setBulkTargetFileName(file.name);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const wb = XLSX.read(e.target.result, { type: "array" });
        const sheet = wb.Sheets[wb.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(sheet, { defval: "" });
        const validated = rows.map((r, i) => {
          const empIdRaw = String(r["Employee ID"] || "").trim();
          const emp = users.find((u) => u.employeeId === empIdRaw) || users.find((u) => u.name.toLowerCase() === String(r["Employee Name (optional, for reference)"] || "").trim().toLowerCase());
          const targetType = String(r["Target Type"] || "").trim();
          const amount = Number(r["Target Amount"]);
          const frequency = String(r["Frequency"] || "").trim();
          const startDate = String(r["Start Date (YYYY-MM-DD)"] || "").trim();
          const endDate = String(r["End Date (YYYY-MM-DD)"] || "").trim();
          const remarks = String(r["Remarks"] || "").trim();
          const errors = [];
          if (!emp) errors.push("Employee ID not found");
          if (!TARGET_TYPES.includes(targetType)) errors.push("Invalid Target Type");
          if (!amount || Number.isNaN(amount) || amount <= 0) errors.push("Target Amount must be a positive number");
          if (!TARGET_FREQUENCIES.includes(frequency)) errors.push("Invalid Frequency");
          if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate)) errors.push("Invalid Start Date");
          if (!/^\d{4}-\d{2}-\d{2}$/.test(endDate)) errors.push("Invalid End Date");
          if (startDate && endDate && endDate < startDate) errors.push("End Date before Start Date");
          return { rowNum: i + 2, employeeId: emp?.employeeId, employeeName: emp?.name, targetType, amount, frequency, startDate, endDate, remarks, errors, valid: errors.length === 0 };
        });
        setBulkTargetRows(validated);
      } catch (err) {
        setFlash(`Could not read file: ${err.message}`);
        setBulkTargetRows([]);
      }
    };
    reader.readAsArrayBuffer(file);
  }

  function commitBulkTargets() {
    const validRows = bulkTargetRows.filter((r) => r.valid);
    if (validRows.length === 0) { setFlash("No valid rows to import"); return; }
    const timestamp = bankDateLabel + " " + new Date().toTimeString().slice(0, 5);
    let nextNum = targets.length;
    const newTargets = validRows.map((r) => {
      nextNum += 1;
      return {
        id: "TGT" + String(nextNum).padStart(3, "0"), employeeId: r.employeeId, employeeName: r.employeeName, targetType: r.targetType, targetValue: r.amount,
        frequency: r.frequency, startDate: r.startDate, endDate: r.endDate, assignedBy: currentUser.name, assignedDate: bankDateLabel, remarks: r.remarks,
        lastUpdated: timestamp, lastUpdatedBy: currentUser.name, milestonesNotified: [],
      };
    });
    setTargets((t) => [...t, ...newTargets]);
    setTargetAuditLog((log) => [
      { id: "TA" + Date.now(), date: timestamp, user: currentUser.name, action: "Bulk Target Upload", detail: `${newTargets.length} target(s) imported from ${bulkTargetFileName}` },
      ...log,
    ]);
    setFlash(`${newTargets.length} target(s) imported successfully`);
    setBulkTargetRows([]);
    setBulkTargetFileName("");
    setShowBulkTargetUpload(false);
  }

