          const description = String(r["Description"] || "").trim();
          const dueDate = String(r["Due Date (YYYY-MM-DD)"] || "").trim();
          const priority = String(r["Priority"] || "").trim();
          const errors = [];
          if (!emp) errors.push("Employee ID not found");
