  function parseSchemeRate(scheme) {
    const m = (scheme || "").match(/(\d+)M @ ([\d.]+)%/);
    return m ? { months: Number(m[1]), rate: Number(m[2]) } : { months: 12, rate: 6 };
  }

  function addMonthsLabel(months) {
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const d = new Date(bankDateObj);
    d.setMonth(d.getMonth() + months);
    return `${String(d.getDate()).padStart(2, "0")} ${monthNames[d.getMonth()]} ${d.getFullYear()}`;
  }

  function addMonthsToISODate(isoDate, months) {
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    if (!isoDate) return "—";
    const [y, m, d] = isoDate.split("-").map(Number);
    const dt = new Date(y, m - 1, d);
    dt.setMonth(dt.getMonth() + Number(months || 0));
    return `${String(dt.getDate()).padStart(2, "0")} ${monthNames[dt.getMonth()]} ${dt.getFullYear()}`;
  }

  function computeEMI(principal, annualRatePct, tenureMonths, interestType) {
    const p = Number(principal), r = Number(annualRatePct), n = Number(tenureMonths);
    if (!p || !r || !n) return 0;
    if (interestType === "Flat") {
      const totalInterest = p * (r / 100) * (n / 12);
      return Math.round(((p + totalInterest) / n) * 100) / 100;
    }
    const monthlyRate = r / 100 / 12;
    const emi = (p * monthlyRate * Math.pow(1 + monthlyRate, n)) / (Math.pow(1 + monthlyRate, n) - 1);
    return Math.round(emi * 100) / 100;
  }

  function computeLoanSummary(principal, annualRatePct, tenureMonths, interestType) {
    const p = Number(principal) || 0, n = Number(tenureMonths) || 0;
    const emi = computeEMI(p, annualRatePct, n, interestType);
    const totalRepayment = Math.round(emi * n * 100) / 100;
    const totalInterest = Math.round((totalRepayment - p) * 100) / 100;
    return { emi, totalRepayment, totalInterest: totalInterest > 0 ? totalInterest : 0 };
  }

  function buildAmortizationSchedule(principal, annualRatePct, tenureMonths, interestType, startDate) {
    const p = Number(principal), r = Number(annualRatePct), n = Number(tenureMonths);
    if (!p || !r || !n) return [];
    const emi = computeEMI(p, annualRatePct, n, interestType);
    const monthlyRate = r / 100 / 12;
    const flatMonthlyInterest = (p * (r / 100) * (n / 12)) / n;
    let balance = p;
    const rows = [];
    for (let i = 1; i <= n; i++) {
      let interestPortion, principalPortion;
      if (interestType === "Flat") {
        interestPortion = Math.round(flatMonthlyInterest * 100) / 100;
        principalPortion = Math.round((emi - interestPortion) * 100) / 100;
      } else {
        interestPortion = Math.round(balance * monthlyRate * 100) / 100;
        principalPortion = Math.round((emi - interestPortion) * 100) / 100;
      }
      balance = Math.round((balance - principalPortion) * 100) / 100;
      rows.push({ month: i, dueDate: addMonthsToISODate(startDate, i), emi, principal: principalPortion, interest: interestPortion, balance: Math.max(0, balance) });
    }
    return rows;
  }

