  function downloadLedgerCsv() {
    const rows = getLedgerExportRows();
    if (!rows.length) { setFlash("No ledger entries to export"); return; }
    try {
      const headers = Object.keys(rows[0]);
      const escape = (v) => { const s = String(v ?? ""); return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
      const csv = [headers.join(","), ...rows.map((r) => headers.map((h) => escape(r[h])).join(","))].join("\n");
      const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `Ledger_${selectedLedgerAccount.id}_24-07-2026.csv`;
      a.click();
      URL.revokeObjectURL(url);
      setFlash(`Ledger downloaded as CSV — ${rows.length} row(s)`);
    } catch (err) {
      setFlash(`Could not export: ${err.message}`);
    }
  }

