  function generateVoterList(asOfDate, meetingId) {
    if (!asOfDate) { setFlash("Select an 'as of' date for the voter list"); return; }
    const asOfDateObj = new Date(asOfDate);
    const entries = members.map((m) => {
      const customerLoans = loans.filter((l) => l.customerNo === m.customerNo);
      const elig = computeVoterEligibility(m, customerLoans, asOfDateObj, voterEligibilityConfig);
      return { memberId: m.id, name: m.name, memberType: m.memberType, shares: m.shares, admissionDate: m.admissionDate, ...elig };
    });
    const meeting = meetingId ? meetings.find((mt) => mt.id === meetingId) : null;
    const record = {
      id: "VL" + Date.now(), asOfDate, meetingId: meetingId || "", meetingNo: meeting?.meetingNo || "",
      generatedBy: currentUser.name, generatedDate: bankDateLabel, config: { ...voterEligibilityConfig }, entries,
      eligibleCount: entries.filter((e) => e.eligible).length, totalCount: entries.length,
    };
    setGeneratedVoterLists((l) => [record, ...l]);
    logSettingChange("Voter List", record.id, "—", `Generated by ${currentUser.name} as of ${asOfDate}${meeting ? ` for ${meeting.meetingNo}` : ""} — ${record.eligibleCount}/${record.totalCount} eligible`);
    setFlash(`Voter list generated — ${record.eligibleCount} of ${record.totalCount} members eligible`);
    return record;
  }

