                            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", border: "1px solid var(--teal)", background: "var(--brand-light)", borderRadius: 8, padding: "9px 12px" }}>
                              <div><strong>{selectedCust.name}</strong> ({selectedCust.id})</div>
                              <button type="button" className="cbs-report-btn" onClick={() => setCallDepositForm({ ...callDepositForm, customerNo: "", sourceAccountId: "" })}>Change</button>
                            </div>
